import { Fragment, memo } from 'react';

import { Cover } from 'components';
import { KPI_CONFIGS } from 'pages/pillars/ValueCreation/VolumePages/config';
import { useVolumePagesKpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { GlobalMovesSection } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/components/GlobalMovesSection';
import { GrowthLeverSection } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/components/GrowthLeverSection';
import {
  buildGrowthLeverMainSubFilters,
  volumePagePrefixedTestId,
} from 'pages/pillars/ValueCreation/VolumePages/utils';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import {
  pageSections,
  SUMMARY_CORONA_SECTION_OVERRIDES,
  SUMMARY_GLOBAL_MOVES_KEYS,
  SUMMARY_GROWTH_LEVER_KEYS,
  SUMMARY_GROWTH_LEVER_SECTION_OVERRIDES,
} from '../../constants';
import { SummaryGlobalMovesSectionProps } from './types';

export const SummaryGlobalMovesSection = memo(
  ({
    getPageByName,
    dataTestId,
    period,
    dt_end,
    kpiEndpoints,
    reporttype,
  }: SummaryGlobalMovesSectionProps) => {
    const { kpi } = useVolumePagesKpi();

    return (
      <>
        <StyledExportPageSection data-page-name={pageSections.globalMovesCover}>
          <Cover
            category="One Way Reports"
            name="Global Moves"
            centerText
            centerLogo
            showLogo
            showLink={false}
            dataTestId={volumePagePrefixedTestId(
              dataTestId,
              'summary-global-moves-cover',
            )}
          />
        </StyledExportPageSection>

        <GlobalMovesSection
          moveKeys={[...SUMMARY_GLOBAL_MOVES_KEYS]}
          sectionOverrides={{ corona: SUMMARY_CORONA_SECTION_OVERRIDES }}
          getPageByName={getPageByName}
          dataTestId={dataTestId}
          period={period}
          dt_end={dt_end}
          kpiEndpoints={kpiEndpoints}
        />

        {SUMMARY_GROWTH_LEVER_KEYS.map((leverKey) => {
          const leverConfig = KPI_CONFIGS[kpi].growthLevers[leverKey];

          if (!leverConfig) return null;

          const mainSubFilters = buildGrowthLeverMainSubFilters(
            leverConfig.mainSubFilters,
            { dt_end, kpi, reporttype },
          );

          return (
            <Fragment key={leverKey}>
              <GrowthLeverSection
                prioritiesPageType={leverConfig.prioritiesPageType}
                prioritiesGrowthLever={leverConfig.prioritiesGrowthLever}
                portfolioConfig={leverConfig.portfolioConfig}
                mainSubFilters={mainSubFilters}
                kpiEndpoints={kpiEndpoints}
                tableOrder={leverConfig.tableOrder}
                getPageByName={getPageByName}
                dataTestId={dataTestId}
                config={leverConfig}
                period={period}
                dt_end={dt_end}
                leverKey={leverKey}
                hideTopBrands
                sectionOverrides={
                  SUMMARY_GROWTH_LEVER_SECTION_OVERRIDES[leverKey]
                }
              />
            </Fragment>
          );
        })}
      </>
    );
  },
);

SummaryGlobalMovesSection.displayName = 'SummaryGlobalMovesSection';
